import pandas as pd

# Analyze seasonal patterns across S2-S5 to understand regime differences
trips = tables['trips'].copy()

# Add season windows
def get_window(doy):
    if 90 <= doy <= 150:
        return 'Spring'
    elif 151 <= doy <= 240:
        return 'Summer'
    elif 241 <= doy <= 310:
        return 'Fall'
    else:
        return 'Other'

trips['window'] = trips['fish_date_doy'].apply(get_window)

# Group by season, window, and class
seasonal = trips[trips['fish_date_season'].isin([2, 3, 4, 5])].groupby(
    ['fish_date_season', 'window', 'cls']
).agg({
    'yt': ['count', 'sum', 'mean']
}).round(2)

seasonal.columns = ['trips', 'total_yt', 'avg_yt_per_trip']
seasonal = seasonal.reset_index()
seasonal = seasonal[seasonal['trips'] > 5]  # Filter small samples

result = seasonal.sort_values(['fish_date_season', 'window', 'total_yt'], ascending=[False, True, False])
print(result.to_string())
